mapper.select:
SELECT u.id AS userId, u.username, u.name, u.status AS userStatus, ut.status AS memberStatus, ut.dept_id AS deptId FROM sys_user_tenant ut INNER JOIN sys_user u ON u.id = ut.user_id AND u.deleted = 0 WHERE ut.tenant_id = #{scope.tenantId} AND ut.deleted = 0
AND (
ut.dept_id IN
#{deptId}
OR ut.user_id = #{scope.userId}
ut.user_id = #{scope.userId}
1 = 0
)
ORDER BY u.id
